import { Button, Input, LayerCard, Link as KumoLink } from "@cloudflare/kumo";
import { useForm } from "@tanstack/react-form";
import { createFileRoute } from "@tanstack/react-router";
import { useState } from "react";

export const Route = createFileRoute("/sign-in")({ component: SignInPage });

function SignInPage() {
  const [message, setMessage] = useState<string>();
  const form = useForm({
    defaultValues: { email: "", password: "" },
    onSubmit: async ({ value }) => {
      const response = await fetch("/api/auth/sign-in/email", {
        body: JSON.stringify(value),
        credentials: "include",
        headers: { "content-type": "application/json" },
        method: "POST",
      });
      setMessage(response.ok ? "Signed in." : "The credentials could not be verified.");
    },
  });

  return (
    <section className="mx-auto max-w-xl px-5 py-14 sm:px-8 sm:py-20">
      <p className="text-sm font-medium uppercase text-(--tangerine)">Welcome back</p>
      <h1 className="mt-4 font-display text-5xl font-semibold leading-none text-kumo-strong">
        Your identity, with fewer sharp edges.
      </h1>
      <LayerCard className="mt-10 bg-kumo-elevated px-5 py-4 ring ring-kumo-line">
        <h2 className="text-2xl font-semibold text-kumo-strong">Sign in</h2>
        <p className="mt-2 text-sm text-kumo-subtle">
          M0 uses Better Auth email/password as its first protocol probe.
        </p>
        <form
          className="mt-6 space-y-5"
          onSubmit={(event) => {
            event.preventDefault();
            void form.handleSubmit();
          }}
        >
          <form.Field name="email">
            {(field) => (
              <Input
                id="email"
                autoComplete="email"
                className="text-sm transition-none"
                label="Email"
                onChange={(event) => field.handleChange(event.target.value)}
                value={field.state.value}
              />
            )}
          </form.Field>
          <form.Field name="password">
            {(field) => (
              <Input
                id="password"
                autoComplete="current-password"
                className="text-sm transition-none"
                label="Password"
                onChange={(event) => field.handleChange(event.target.value)}
                type="password"
                value={field.state.value}
              />
            )}
          </form.Field>
          <Button className="w-full text-sm transition-none" type="submit" variant="primary">
            Continue
          </Button>
          {message ? (
            <p className="text-sm text-kumo-brand" role="status">
              {message}
            </p>
          ) : null}
        </form>
        <KumoLink className="mt-5 inline-block text-sm transition-none" href="/" variant="plain">
          Back to overview
        </KumoLink>
      </LayerCard>
    </section>
  );
}

