import { Elysia, t } from "elysia";

import { type AuthEnvironment, createAuth } from "./auth";

function authHandler(environment: AuthEnvironment) {
  return ({ request }: { request: Request }) => createAuth(environment).handler(request);
}

export function createApiApp(environment: AuthEnvironment) {
  const handleAuth = authHandler(environment);

  return new Elysia({ aot: false, prefix: "/api" })
    .get("/health", () => ({ service: "shui-api", status: "ok" as const }), {
      response: t.Object({
        service: t.String(),
        status: t.Literal("ok"),
      }),
    })
    .head("/health", () => new Response(null, { status: 204 }))
    .get("/auth", handleAuth)
    .post("/auth", handleAuth)
    .put("/auth", handleAuth)
    .patch("/auth", handleAuth)
    .delete("/auth", handleAuth)
    .options("/auth", handleAuth)
    .head("/auth", handleAuth)
    .get("/auth/*", handleAuth)
    .post("/auth/*", handleAuth)
    .put("/auth/*", handleAuth)
    .patch("/auth/*", handleAuth)
    .delete("/auth/*", handleAuth)
    .options("/auth/*", handleAuth)
    .head("/auth/*", handleAuth);
}

export type ApiApp = ReturnType<typeof createApiApp>;

